/**
 * A slideshow over the screenshots of the last e2e run — the thing the HTML
 * report cannot do (its tests are one page each, and it is generated by
 * Playwright, so nothing can be added to it).
 *
 *   npm run test:e2e:gallery            # build tmp/e2e/gallery and serve it
 *   npm run test:e2e:gallery -- --port 9400
 *
 * It reads `tmp/e2e/manifest.json` — written by `support/manifest-reporter.mjs`
 * on every local run — and serves `tmp/e2e` on one port, so the page and the
 * screenshots it points at live under the same root.
 */
import fs from "node:fs";
import http from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "tmp", "e2e");
const MANIFEST = path.join(DATA, "manifest.json");
const PAGE = path.join(DATA, "gallery", "index.html");

const args = process.argv.slice(2);
const portArg = args.indexOf("--port");
const PORT = portArg === -1 ? 9324 : Number(args[portArg + 1]);
const BUILD_ONLY = args.includes("--no-serve");

const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
  ".svg": "image/svg+xml",
  ".zip": "application/zip",
};

function readRun() {
  if (!fs.existsSync(MANIFEST)) {
    console.error(
      "e2e gallery: no run to show.\n" +
        "The slideshow reads what a run leaves behind, so run one first:\n\n" +
        "  npm run test:e2e\n",
    );
    process.exit(1);
  }
  const tests = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
  const shots = tests.filter((test) => test.screenshot);
  if (!shots.length) {
    console.error(
      "e2e gallery: the last run kept no screenshots — it ran with `screenshot: only-on-failure`\n" +
        "(that is what CI does). Locally every test keeps one; run `npm run test:e2e` here.",
    );
    process.exit(1);
  }
  return { tests, shots, taken: fs.statSync(MANIFEST).mtime };
}

function build({ shots, taken }) {
  const items = shots.map((test) => ({
    src: `../${test.screenshot}`,
    project: test.project,
    group: test.group,
    title: test.title,
    status: test.status,
    duration: test.duration,
  }));
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>e2e screenshots</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body { margin: 0; background: #16181d; color: #e6e8ec; font: 14px/1.4 system-ui, -apple-system, Segoe UI, sans-serif; }
  header { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; padding: 12px 16px; border-bottom: 1px solid #2a2e37; }
  h1 { margin: 0; font-size: 15px; font-weight: 600; }
  h1 span { color: #8b93a3; font-weight: 400; margin-left: 8px; }
  nav { display: flex; gap: 6px; margin-left: auto; }
  nav button { background: #232732; color: #cfd4de; border: 1px solid #333846; border-radius: 999px; padding: 4px 12px; font: inherit; cursor: pointer; }
  nav button[aria-pressed="true"] { background: #2f6feb; border-color: #2f6feb; color: #fff; }
  header a { color: #8ab4ff; text-decoration: none; }
  main { padding: 16px; display: flex; flex-direction: column; gap: 12px; }
  .stage { position: relative; display: flex; align-items: center; justify-content: center; background: #101216; border: 1px solid #2a2e37; border-radius: 10px; min-height: 46vh; }
  .stage img { max-width: 100%; max-height: 62vh; border-radius: 6px; cursor: zoom-in; }
  /* Full screen is the stage itself, not the page: the picture takes the whole
     screen, the bar below it goes away, and the keys keep working — a browser
     that refuses the request (an embedded frame, a policy) gets a stage pinned
     over the viewport instead, so the button always does something. */
  .stage:fullscreen, body.stage-full .stage { border: 0; border-radius: 0; background: #000; width: 100vw; height: 100vh; min-height: 0; }
  body.stage-full .stage { position: fixed; inset: 0; z-index: 50; }
  .stage:fullscreen img, body.stage-full .stage img { max-width: 100vw; max-height: 100vh; border-radius: 0; cursor: zoom-out; }
  .hud { display: none; }
  .stage:fullscreen .hud, body.stage-full .hud {
    display: flex; gap: 10px; align-items: baseline; position: absolute; left: 14px; bottom: 14px;
    padding: 6px 12px; border-radius: 8px; background: rgba(16, 18, 22, .78); color: #cfd4de; font-size: 13px;
  }
  .hud span:first-child { color: #8b93a3; font-variant-numeric: tabular-nums; }
  .bar { display: flex; gap: 8px; align-items: center; }
  .bar button, .bar select { background: #232732; color: #e6e8ec; border: 1px solid #333846; border-radius: 8px; padding: 6px 14px; font: inherit; cursor: pointer; }
  .bar button:hover { background: #2c313d; }
  .bar #counter { color: #8b93a3; margin-left: 4px; font-variant-numeric: tabular-nums; }
  .caption { display: flex; flex-wrap: wrap; gap: 10px; align-items: baseline; }
  .badge { background: #1f3a63; color: #9cc3ff; border-radius: 999px; padding: 1px 9px; font-size: 12px; }
  .caption .group { color: #8b93a3; }
  .caption strong { font-weight: 600; }
  .caption .meta { color: #8b93a3; font-size: 12px; }
  .thumbs { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 6px; }
  .thumbs button { padding: 0; border: 2px solid transparent; border-radius: 6px; background: none; cursor: pointer; flex: 0 0 auto; }
  .thumbs button[aria-current="true"] { border-color: #2f6feb; }
  .thumbs img { display: block; height: 64px; width: auto; border-radius: 4px; opacity: .7; }
  .thumbs button[aria-current="true"] img { opacity: 1; }
</style>
</head>
<body>
<header>
  <h1>e2e screenshots<span id="total"></span></h1>
  <nav id="projects"></nav>
  <a href="http://localhost:9323/" target="_blank" rel="noreferrer">Report ↗</a>
</header>
<main>
  <div class="stage" id="stage">
    <img id="shot" alt="" title="Click or press F for full screen">
    <div class="hud"><span id="hudCounter"></span><span id="hudTitle"></span></div>
  </div>
  <div class="bar">
    <button id="prev" title="Previous (←)">‹</button>
    <button id="play" title="Play / pause (Space)">▶</button>
    <button id="next" title="Next (→)">›</button>
    <button id="full" title="Full screen (F)">⛶</button>
    <span id="counter"></span>
    <select id="speed" title="Slide time">
      <option value="1000">1 s</option>
      <option value="2000" selected>2 s</option>
      <option value="4000">4 s</option>
    </select>
  </div>
  <div class="caption">
    <span class="badge" id="badge"></span>
    <span class="group" id="group"></span>
    <strong id="title"></strong>
    <span class="meta" id="meta"></span>
  </div>
  <div class="thumbs" id="thumbs"></div>
</main>
<script>
const ITEMS = ${JSON.stringify(items)};
const TAKEN = ${JSON.stringify(taken.toISOString())};
let filter = "all", list = [], at = 0, timer = null;
const $ = (id) => document.getElementById(id);
const shot = $("shot");
const stage = $("stage");
/** Set when the browser refused requestFullscreen and the stage is pinned instead. */
let pinned = false;
const inFull = () => document.fullscreenElement === stage || pinned;

function syncFull() {
  $("full").textContent = inFull() ? "⤡" : "⛶";
  $("full").setAttribute("aria-pressed", String(inFull()));
}

async function toggleFull() {
  if (inFull()) {
    if (document.fullscreenElement) await document.exitFullscreen().catch(() => {});
    pinned = false;
    document.body.classList.remove("stage-full");
    syncFull();
    return;
  }
  try {
    await stage.requestFullscreen();
  } catch {
    pinned = true;
    document.body.classList.add("stage-full");
  }
  syncFull();
}

function projects() { return [...new Set(ITEMS.map((i) => i.project))]; }

function renderProjects() {
  const nav = $("projects");
  nav.textContent = "";
  for (const name of ["all", ...projects()]) {
    const b = document.createElement("button");
    b.textContent = name;
    b.setAttribute("aria-pressed", String(filter === name));
    b.onclick = () => { filter = name; apply(); };
    nav.append(b);
  }
}

function apply() {
  list = filter === "all" ? ITEMS.slice() : ITEMS.filter((i) => i.project === filter);
  at = 0;
  renderProjects();
  renderThumbs();
  show();
}

function show() {
  const item = list[at];
  if (!item) return;
  shot.src = item.src;
  shot.alt = item.title;
  $("badge").textContent = item.project;
  $("group").textContent = item.group ? item.group + " ›" : "";
  $("title").textContent = item.title;
  $("meta").textContent = (item.status === "passed" ? "" : item.status + " · ") + (item.duration / 1000).toFixed(1) + " s";
  $("counter").textContent = (at + 1) + " / " + list.length;
  // The bar is off screen in full screen, so the frame carries its own caption.
  $("hudCounter").textContent = (at + 1) + " / " + list.length;
  $("hudTitle").textContent = item.title;
  const next = list[at + 1];
  new Image().src = next ? next.src : ITEMS[0].src;
  for (const [i, b] of [...$("thumbs").children].entries()) b.setAttribute("aria-current", String(i === at));
  $("thumbs").children[at]?.scrollIntoView({ block: "nearest", inline: "center" });
}

function step(by) {
  if (!list.length) return;
  at = (at + by + list.length) % list.length;
  show();
}

function play(on) {
  clearInterval(timer);
  timer = on ? setInterval(() => step(1), Number($("speed").value)) : null;
  $("play").textContent = on ? "❚❚" : "▶";
}

function renderThumbs() {
  const box = $("thumbs");
  box.textContent = "";
  for (const [i, item] of list.entries()) {
    const b = document.createElement("button");
    b.append(Object.assign(document.createElement("img"), { src: item.src, alt: item.title }));
    b.onclick = () => { at = i; show(); };
    box.append(b);
  }
}

$("prev").onclick = () => step(-1);
$("next").onclick = () => step(1);
$("play").onclick = () => play(!timer);
$("speed").onchange = () => { if (timer) play(true); };
$("full").onclick = () => toggleFull();
// The picture itself is the way in and out — the click that a lightbox answers to.
shot.onclick = () => toggleFull();
document.addEventListener("fullscreenchange", syncFull);
addEventListener("keydown", (e) => {
  if (e.key === "ArrowLeft") step(-1);
  else if (e.key === "ArrowRight") step(1);
  else if (e.key === " ") { e.preventDefault(); play(!timer); }
  else if (e.key === "Home") { at = 0; show(); }
  else if (e.key === "End") { at = list.length - 1; show(); }
  else if (e.key === "f" || e.key === "F") toggleFull();
  else if (e.key === "Escape" && pinned) toggleFull();
});
$("total").textContent = " · " + ITEMS.length + " tests · " + new Date(TAKEN).toLocaleString();
apply();
</script>
</body>
</html>
`;
  fs.mkdirSync(path.dirname(PAGE), { recursive: true });
  fs.writeFileSync(PAGE, html);
  return items.length;
}

function serve() {
  const server = http.createServer((req, res) => {
    let url = decodeURIComponent((req.url || "/").split("?")[0]);
    if (url === "/") url = "/gallery/index.html";
    else if (url.endsWith("/")) url += "index.html";
    const file = path.join(DATA, url);
    // Never read outside tmp/e2e — the page asks for `data/...` of its own run.
    if (!file.startsWith(DATA)) {
      res.writeHead(403).end("forbidden");
      return;
    }
    fs.readFile(file, (err, body) => {
      if (err) {
        res.writeHead(404).end("not found");
        return;
      }
      res.writeHead(200, { "Content-Type": TYPES[path.extname(file).toLowerCase()] ?? "application/octet-stream" });
      res.end(body);
    });
  });
  server.listen(PORT, "127.0.0.1", () => {
    console.log(`e2e screenshots: http://127.0.0.1:${PORT}/gallery/`);
    console.log("← / → листать · Space пауза · чипы сверху — проект");
  });
}

const run = readRun();
const count = build(run);
console.log(`e2e gallery: ${count} screenshots → ${path.relative(ROOT, PAGE)}`);
if (!BUILD_ONLY) serve();
